-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_rsvps_name(p_rsvp_id TEXT)
RETURNS TEXT AS $$
  SELECT ((SELECT NULLIF(rsvp_id, '') FROM rsvps WHERE rsvp_id = p_rsvp_id))::text;
$$ LANGUAGE sql STABLE;

-- calc_rsvps_event_name
-- Field: RSVPs.EventName
-- Type: lookup | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_rsvps_event_name(p_rsvp_id TEXT)
RETURNS TEXT AS $$
  SELECT ((SELECT NULLIF(event_ref, '') FROM rsvps WHERE rsvp_id = p_rsvp_id))::text;
$$ LANGUAGE sql STABLE;

-- calc_rsvps_attendee_name
-- Field: RSVPs.AttendeeName
-- Type: lookup | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_rsvps_attendee_name(p_rsvp_id TEXT)
RETURNS TEXT AS $$
  SELECT ((SELECT NULLIF(attendee_ref, '') FROM rsvps WHERE rsvp_id = p_rsvp_id))::text;
$$ LANGUAGE sql STABLE;

