  calc_attendees_name(t.attendee_id) AS name                                    -- Display name for the attendee
FROM attendees t;

-- ----------------------------------------------------------------------------
-- vw_rsvps: Table: RSVPs (many-to-many: Events to Attendees)
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_rsvps CASCADE;
CREATE VIEW vw_rsvps WITH (security_invoker = ON) AS
SELECT
  t.rsvp_id,                                                                    -- Unique RSVP identifier
  calc_rsvps_name(t.rsvp_id) AS name,                                           -- Display name
  t.event_ref,                                                                  -- Related event
  calc_rsvps_event_name(t.rsvp_id) AS event_name,                               -- Looked up event name
  t.attendee_ref,                                                               -- Related attendee
  calc_rsvps_attendee_name(t.rsvp_id) AS attendee_name,                         -- Looked up attendee name
  t.status                                                                      -- RSVP status (confirmed, waitlist, declined)
FROM rsvps t;



